var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# nopasswd-sudo.sh — toggle temporary passwordless sudo for a user."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# Handy during migration/maintenance sessions that run many sudo commands"},
{"lineNum":"    6","line":"# non-interactively (e.g. driven over SSH). Turn it ON at the start, OFF when"},
{"lineNum":"    7","line":"# done. The drop-in is validated with `visudo` before being installed, so a"},
{"lineNum":"    8","line":"# typo can\'t lock you out of sudo."},
{"lineNum":"    9","line":"#"},
{"lineNum":"   10","line":"# Enabling also arms an auto-revoke so you can never leave passwordless sudo on"},
{"lineNum":"   11","line":"# by accident: an in-session timer switches it OFF after the timeout (default"},
{"lineNum":"   12","line":"# 30 min; pass a different number of minutes, or 0 to disable), AND a persistent"},
{"lineNum":"   13","line":"# boot-time unit clears it on every reboot. The in-session timer is transient"},
{"lineNum":"   14","line":"# and does NOT survive a reboot, so the boot unit is the reboot safety net —"},
{"lineNum":"   15","line":"# without it, a reboot would strand the grant with nothing left to revoke it."},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Usage:"},
{"lineNum":"   18","line":"#   sudo ./nopasswd-sudo.sh on   [user] [minutes]   # default user: $SUDO_USER, default 30 min"},
{"lineNum":"   19","line":"#   sudo ./nopasswd-sudo.sh off"},
{"lineNum":"   20","line":"#   sudo ./nopasswd-sudo.sh status"},
{"lineNum":"   21","line":"#"},
{"lineNum":"   22","line":"set -o errexit","class":"lineCov","hits":"1","order":"477",},
{"lineNum":"   23","line":"set -o nounset","class":"lineCov","hits":"1","order":"484",},
{"lineNum":"   24","line":"set -o pipefail","class":"lineCov","hits":"1","order":"485",},
{"lineNum":"   25","line":""},
{"lineNum":"   26","line":"readonly DROPIN=\"/etc/sudoers.d/99-temp-nopasswd\"","class":"lineCov","hits":"1","order":"478",},
{"lineNum":"   27","line":"readonly AUTO_UNIT=\"nopasswd-sudo-autorevoke\"","class":"lineCov","hits":"1","order":"479",},
{"lineNum":"   28","line":"readonly BOOT_UNIT=\"nopasswd-sudo-bootrevoke\"","class":"lineCov","hits":"1","order":"480",},
{"lineNum":"   29","line":"readonly DEFAULT_TIMEOUT_MIN=30","class":"lineCov","hits":"1","order":"476",},
{"lineNum":"   30","line":""},
{"lineNum":"   31","line":"#######################################"},
{"lineNum":"   32","line":"# Log an informational message to stdout."},
{"lineNum":"   33","line":"#######################################"},
{"lineNum":"   34","line":"log_info() { printf \'%s\\n\' \"$*\"; }"},
{"lineNum":"   35","line":""},
{"lineNum":"   36","line":"#######################################"},
{"lineNum":"   37","line":"# Log an error message to stderr."},
{"lineNum":"   38","line":"#######################################"},
{"lineNum":"   39","line":"log_error() { printf \'ERROR: %s\\n\' \"$*\" >&2; }"},
{"lineNum":"   40","line":""},
{"lineNum":"   41","line":"#######################################"},
{"lineNum":"   42","line":"# Print usage information."},
{"lineNum":"   43","line":"#######################################"},
{"lineNum":"   44","line":"show_usage() {"},
{"lineNum":"   45","line":"  cat <<EOF","class":"lineCov","hits":"1","order":"481",},
{"lineNum":"   46","line":"Usage: sudo $(basename \"$0\") {on|off|status} [user] [minutes]"},
{"lineNum":"   47","line":""},
{"lineNum":"   48","line":"  on [user] [minutes]   grant passwordless sudo (default user: \\${SUDO_USER:-root})"},
{"lineNum":"   49","line":"                        and arm auto-revoke after [minutes] (default ${DEFAULT_TIMEOUT_MIN}; 0 = never)"},
{"lineNum":"   50","line":"  off                   revoke it now (removes ${DROPIN}, cancels the timer)"},
{"lineNum":"   51","line":"  status                show whether it is enabled and any armed auto-revoke"},
{"lineNum":"   52","line":""},
{"lineNum":"   53","line":"Examples:"},
{"lineNum":"   54","line":"  sudo $(basename \"$0\") on            # enable for \\$SUDO_USER, auto-off in ${DEFAULT_TIMEOUT_MIN} min"},
{"lineNum":"   55","line":"  sudo $(basename \"$0\") on 90         # enable for \\$SUDO_USER, auto-off in 90 min"},
{"lineNum":"   56","line":"  sudo $(basename \"$0\") on jure 0     # enable for jure, no auto-revoke"},
{"lineNum":"   57","line":"EOF"},
{"lineNum":"   58","line":"}"},
{"lineNum":"   59","line":""},
{"lineNum":"   60","line":"#######################################"},
{"lineNum":"   61","line":"# Abort unless running as root."},
{"lineNum":"   62","line":"#######################################"},
{"lineNum":"   63","line":"require_root() {"},
{"lineNum":"   64","line":"  if [[ \"${EUID}\" -ne 0 ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"   65","line":"    log_error \"must run as root (use sudo).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   66","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   67","line":"  fi"},
{"lineNum":"   68","line":"}"},
{"lineNum":"   69","line":""},
{"lineNum":"   70","line":"#######################################"},
{"lineNum":"   71","line":"# Enable passwordless sudo for a user via a validated sudoers drop-in."},
{"lineNum":"   72","line":"# Globals:"},
{"lineNum":"   73","line":"#   DROPIN"},
{"lineNum":"   74","line":"# Arguments:"},
{"lineNum":"   75","line":"#   Target user (defaults to ${SUDO_USER})."},
{"lineNum":"   76","line":"#######################################"},
{"lineNum":"   77","line":"enable_nopasswd() {"},
{"lineNum":"   78","line":"  local user=\"${1:-${SUDO_USER:-}}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   79","line":"  if [[ -z \"${user}\" ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"   80","line":"    log_error \"could not determine target user; pass one explicitly.\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   81","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   82","line":"  fi"},
{"lineNum":"   83","line":"  if ! id -u \"${user}\" >/dev/null 2>&1; then","class":"lineNoCov","hits":"0",},
{"lineNum":"   84","line":"    log_error \"no such user: ${user}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   85","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   86","line":"  fi"},
{"lineNum":"   87","line":""},
{"lineNum":"   88","line":"  local tmp","class":"lineNoCov","hits":"0",},
{"lineNum":"   89","line":"  tmp=\"$(mktemp)\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   90","line":"  printf \'%s ALL=(ALL) NOPASSWD:ALL\\n\' \"${user}\" >\"${tmp}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   91","line":""},
{"lineNum":"   92","line":"  # Validate BEFORE installing — a bad sudoers file can lock you out of sudo."},
{"lineNum":"   93","line":"  if ! visudo -cf \"${tmp}\" >/dev/null; then","class":"lineNoCov","hits":"0",},
{"lineNum":"   94","line":"    rm -f \"${tmp}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   95","line":"    log_error \"sudoers syntax check failed; not installing.\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   96","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   97","line":"  fi"},
{"lineNum":"   98","line":""},
{"lineNum":"   99","line":"  install -m 0440 -o root -g root \"${tmp}\" \"${DROPIN}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  100","line":"  rm -f \"${tmp}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  101","line":"  log_info \"passwordless sudo ENABLED for \'${user}\' (${DROPIN}).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  102","line":"}"},
{"lineNum":"  103","line":""},
{"lineNum":"  104","line":"#######################################"},
{"lineNum":"  105","line":"# Arm a one-shot systemd timer that runs `off` after the timeout."},
{"lineNum":"  106","line":"# A transient timer is used so it survives this script (and the SSH session)"},
{"lineNum":"  107","line":"# exiting. Re-arming first cancels any existing timer, resetting the clock."},
{"lineNum":"  108","line":"# Globals:"},
{"lineNum":"  109","line":"#   AUTO_UNIT"},
{"lineNum":"  110","line":"# Arguments:"},
{"lineNum":"  111","line":"#   Timeout in minutes (0 disables auto-revoke)."},
{"lineNum":"  112","line":"#######################################"},
{"lineNum":"  113","line":"schedule_revoke() {"},
{"lineNum":"  114","line":"  local minutes=\"${1}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  115","line":"  cancel_revoke","class":"lineNoCov","hits":"0",},
{"lineNum":"  116","line":"  if [[ \"${minutes}\" -eq 0 ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  117","line":"    log_info \"auto-revoke DISABLED (timeout 0) — remember to run \'off\' yourself.\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  118","line":"    return","class":"lineNoCov","hits":"0",},
{"lineNum":"  119","line":"  fi"},
{"lineNum":"  120","line":"  local self","class":"lineNoCov","hits":"0",},
{"lineNum":"  121","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  122","line":"  systemd-run --quiet --unit=\"${AUTO_UNIT}\" --on-active=\"${minutes}min\" \\","class":"lineNoCov","hits":"0",},
{"lineNum":"  123","line":"    --description=\"Auto-revoke temporary passwordless sudo\" \\"},
{"lineNum":"  124","line":"    \"${self}\" off"},
{"lineNum":"  125","line":"  log_info \"auto-revoke ARMED: passwordless sudo self-disables in ${minutes} min.\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  126","line":"}"},
{"lineNum":"  127","line":""},
{"lineNum":"  128","line":"#######################################"},
{"lineNum":"  129","line":"# Cancel any pending auto-revoke timer (idempotent)."},
{"lineNum":"  130","line":"# Globals:"},
{"lineNum":"  131","line":"#   AUTO_UNIT"},
{"lineNum":"  132","line":"#######################################"},
{"lineNum":"  133","line":"cancel_revoke() {"},
{"lineNum":"  134","line":"  systemctl stop \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineNoCov","hits":"0",},
{"lineNum":"  135","line":"  systemctl reset-failed \"${AUTO_UNIT}.service\" \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineNoCov","hits":"0",},
{"lineNum":"  136","line":"}"},
{"lineNum":"  137","line":""},
{"lineNum":"  138","line":"#######################################"},
{"lineNum":"  139","line":"# Install and enable a persistent boot-time unit that revokes passwordless"},
{"lineNum":"  140","line":"# sudo on every boot. The in-session auto-revoke timer is transient and does"},
{"lineNum":"  141","line":"# NOT survive a reboot, so without this a reboot could strand the grant with"},
{"lineNum":"  142","line":"# nothing left to remove it. Idempotent; safe to leave enabled permanently"},
{"lineNum":"  143","line":"# (its `off` is a no-op when no drop-in is present)."},
{"lineNum":"  144","line":"# Globals:"},
{"lineNum":"  145","line":"#   BOOT_UNIT"},
{"lineNum":"  146","line":"#######################################"},
{"lineNum":"  147","line":"ensure_boot_revoke() {"},
{"lineNum":"  148","line":"  local self unit=\"/etc/systemd/system/${BOOT_UNIT}.service\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  149","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  150","line":"  if [[ ! -f \"${unit}\" ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  151","line":"    cat >\"${unit}\" <<UNIT","class":"lineNoCov","hits":"0",},
{"lineNum":"  152","line":"[Unit]"},
{"lineNum":"  153","line":"Description=Revoke temporary passwordless sudo on boot"},
{"lineNum":"  154","line":"After=local-fs.target"},
{"lineNum":"  155","line":""},
{"lineNum":"  156","line":"[Service]"},
{"lineNum":"  157","line":"Type=oneshot"},
{"lineNum":"  158","line":"ExecStart=${self} off"},
{"lineNum":"  159","line":""},
{"lineNum":"  160","line":"[Install]"},
{"lineNum":"  161","line":"WantedBy=multi-user.target"},
{"lineNum":"  162","line":"UNIT"},
{"lineNum":"  163","line":"    systemctl daemon-reload","class":"lineNoCov","hits":"0",},
{"lineNum":"  164","line":"  fi"},
{"lineNum":"  165","line":"  systemctl enable \"${BOOT_UNIT}.service\" >/dev/null 2>&1 || true","class":"lineNoCov","hits":"0",},
{"lineNum":"  166","line":"}"},
{"lineNum":"  167","line":""},
{"lineNum":"  168","line":"#######################################"},
{"lineNum":"  169","line":"# Remove the passwordless sudo drop-in and cancel the auto-revoke timer."},
{"lineNum":"  170","line":"# Globals:"},
{"lineNum":"  171","line":"#   DROPIN"},
{"lineNum":"  172","line":"#######################################"},
{"lineNum":"  173","line":"disable_nopasswd() {"},
{"lineNum":"  174","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  175","line":"    rm -f \"${DROPIN}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  176","line":"    log_info \"passwordless sudo DISABLED (removed ${DROPIN}).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  177","line":"  else"},
{"lineNum":"  178","line":"    log_info \"already disabled (no ${DROPIN}).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  179","line":"  fi"},
{"lineNum":"  180","line":"  cancel_revoke","class":"lineNoCov","hits":"0",},
{"lineNum":"  181","line":"}"},
{"lineNum":"  182","line":""},
{"lineNum":"  183","line":"#######################################"},
{"lineNum":"  184","line":"# Report whether the drop-in is present and whether auto-revoke is armed."},
{"lineNum":"  185","line":"# Globals:"},
{"lineNum":"  186","line":"#   DROPIN"},
{"lineNum":"  187","line":"#   AUTO_UNIT"},
{"lineNum":"  188","line":"#   BOOT_UNIT"},
{"lineNum":"  189","line":"#######################################"},
{"lineNum":"  190","line":"show_status() {"},
{"lineNum":"  191","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  192","line":"    log_info \"ENABLED:\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  193","line":"    sed \'s/^/  /\' \"${DROPIN}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  194","line":"  else"},
{"lineNum":"  195","line":"    log_info \"DISABLED (no ${DROPIN}).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  196","line":"  fi"},
{"lineNum":"  197","line":"  if systemctl is-active --quiet \"${AUTO_UNIT}.timer\" 2>/dev/null; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  198","line":"    log_info \"auto-revoke (this session): ARMED\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  199","line":"    systemctl list-timers \"${AUTO_UNIT}.timer\" --no-pager 2>/dev/null \\","class":"lineNoCov","hits":"0",},
{"lineNum":"  200","line":"      | sed -n \'2p\' | sed \'s/^/  /\'"},
{"lineNum":"  201","line":"  else"},
{"lineNum":"  202","line":"    log_info \"auto-revoke (this session): not armed\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  203","line":"  fi"},
{"lineNum":"  204","line":"  if systemctl is-enabled --quiet \"${BOOT_UNIT}.service\" 2>/dev/null; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  205","line":"    log_info \"boot-revoke: enabled (passwordless sudo is cleared on every reboot)\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  206","line":"  else"},
{"lineNum":"  207","line":"    log_info \"boot-revoke: NOT installed (a reboot would not clear a stale grant)\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  208","line":"  fi"},
{"lineNum":"  209","line":"}"},
{"lineNum":"  210","line":""},
{"lineNum":"  211","line":"#######################################"},
{"lineNum":"  212","line":"# Entry point: dispatch on the requested action."},
{"lineNum":"  213","line":"#######################################"},
{"lineNum":"  214","line":"main() {"},
{"lineNum":"  215","line":"  case \"${1:-}\" in","class":"lineCov","hits":"1","order":"475",},
{"lineNum":"  216","line":"    -h | --help | \"\") show_usage; exit 0 ;;","class":"lineCov","hits":"1","order":"474",},
{"lineNum":"  217","line":"  esac"},
{"lineNum":"  218","line":"  require_root","class":"lineNoCov","hits":"0",},
{"lineNum":"  219","line":"  case \"${1}\" in","class":"lineNoCov","hits":"0",},
{"lineNum":"  220","line":"    on)"},
{"lineNum":"  221","line":"      # on [user] [minutes]; a bare numeric first arg is treated as minutes."},
{"lineNum":"  222","line":"      local user=\"\" minutes=\"${DEFAULT_TIMEOUT_MIN}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  223","line":"      if [[ \"${2:-}\" =~ ^[0-9]+$ ]]; then","class":"lineNoCov","hits":"0",},
{"lineNum":"  224","line":"        minutes=\"${2}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  225","line":"      else"},
{"lineNum":"  226","line":"        user=\"${2:-}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  227","line":"        [[ \"${3:-}\" =~ ^[0-9]+$ ]] && minutes=\"${3}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  228","line":"      fi"},
{"lineNum":"  229","line":"      # Install the boot-time safety net BEFORE granting, so a reboot can never"},
{"lineNum":"  230","line":"      # strand the grant even if everything after this point fails."},
{"lineNum":"  231","line":"      ensure_boot_revoke","class":"lineNoCov","hits":"0",},
{"lineNum":"  232","line":"      enable_nopasswd \"${user}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  233","line":"      schedule_revoke \"${minutes}\"","class":"lineNoCov","hits":"0",},
{"lineNum":"  234","line":"      ;;"},
{"lineNum":"  235","line":"    off)    disable_nopasswd ;;","class":"lineNoCov","hits":"0",},
{"lineNum":"  236","line":"    status) show_status ;;","class":"lineNoCov","hits":"0",},
{"lineNum":"  237","line":"    *)      log_error \"unknown command: ${1}\"; show_usage; exit 2 ;;","class":"lineNoCov","hits":"0",},
{"lineNum":"  238","line":"  esac"},
{"lineNum":"  239","line":"}"},
{"lineNum":"  240","line":""},
{"lineNum":"  241","line":"# Only run when executed, not when sourced — the test suite sources this file to exercise its"},
{"lineNum":"  242","line":"# individual functions."},
{"lineNum":"  243","line":"if [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then","class":"lineCov","hits":"1","order":"482",},
{"lineNum":"  244","line":"  main \"$@\"","class":"lineCov","hits":"1","order":"483",},
{"lineNum":"  245","line":"fi"},
]};
